import {catalog,categories,features} from './catalog.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let mode='places';
let filter='Todos', restore, demoTab='Resumen', storageAvailable=true;
const dialog=$('#dialog'), body=$('#dialog-body');
const initial=[{id:'sample',title:'Un brindis por descubrir',description:'Ejemplo de una experiencia de bienvenida para el Bar de demostración. Sin valor comercial.',start:'2026-11-05',end:'2026-11-30',from:'18:00',to:'20:00',capacity:30,paused:false}];
let offers=structuredClone(initial);try{const stored=JSON.parse(sessionStorage.getItem('lavita-demo')||'null');if(Array.isArray(stored)&&stored.every(o=>typeof o.title==='string'&&typeof o.capacity==='number'))offers=stored;}catch{storageAvailable=false;}
function save(){try{sessionStorage.setItem('lavita-demo',JSON.stringify(offers));return true;}catch{storageAvailable=false;return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',6000);}
function open(content){if(!dialog.open){restore=document.activeElement;body.innerHTML=content;dialog.showModal();}else body.innerHTML=content;dialog.scrollTop=0;$('#close-dialog').focus();}
function close(){dialog.close();restore?.focus();}
$('#close-dialog').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const els=[...dialog.querySelectorAll('button,a[href],input,textarea,select,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
function tile(p){return `<figure class="place-photo"><img src="${p.image.src}" alt="${esc(p.name)} · fotografía del establecimiento" width="800" height="530" loading="${p.index<3?'eager':'lazy'}" decoding="async"><figcaption><a href="${p.image.source}" target="_blank" rel="noopener noreferrer">Foto: ${esc(p.image.credit)} ↗</a></figcaption></figure>`;}
$('#filters').innerHTML=categories.map(c=>`<button aria-pressed="${c===filter}" data-filter="${c}">${c}</button>`).join('');
function render(){if(mode==='discounts') {$('#count').textContent='Descuentos · Próximamente';$('#catalog').innerHTML=`<div class="empty experience-empty"><span class="eyebrow">UN NUEVO MOTIVO PARA SALIR</span><h2>Los beneficios están por llegar.</h2><p>Aún no hay descuentos vigentes. Mientras tanto, descubre diez lugares del barrio.</p><button class="button primary" id="reset-search">Explorar lugares ↗</button></div>`;return;}const query=normalize($('#search').value.trim());const results=catalog.filter(p=>(mode!=='restaurants'||p.id==='cabuya')&&(filter==='Todos'||p.categories.includes(filter))&&normalize([p.name,p.description,...p.categories].join(' ')).includes(query));$('#count').textContent=`${results.length} ${results.length===1?'lugar':'lugares'} en esta selección`;
$('#catalog').innerHTML=results.length?results.map(p=>`<article class="place">${tile(p)}<p class="category">${p.categories.map(esc).join(' · ')}</p><h3>${p.name}</h3><p class="description">${p.description}</p><p class="location">↗ ${p.location}</p><div class="place-actions"><button class="text-button" data-place="${p.id}">Conocer el lugar ↗</button><span class="coming">Beneficios · Próximamente</span></div></article>`).join(''):`<div class="empty"><h3>No encontramos ese lugar.</h3><p>Prueba otro nombre o vuelve a explorar la selección completa.</p><button class="button" id="reset-search">Ver todos los lugares</button></div>`;}
function setMode(next){mode=next;filter='Todos';$('#search').value='';$('#filters').querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',el.dataset.filter===filter));document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));$('#filters').hidden=mode==='discounts';$('.search-row').hidden=mode==='discounts';render();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#nav-discounts').onclick=()=>{setMode('discounts');$('#explorar').scrollIntoView({behavior:'smooth'});};
$('#search').oninput=()=>{render();};$('#filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;$('#filters').querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',el===b));render();};
$('#catalog').onclick=e=>{if(e.target.closest('#reset-search')){setMode('places');$('#search').value='';filter='Todos';$('#filters').querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',el.dataset.filter===filter));render();$('#search').focus();return;}const b=e.target.closest('[data-place]');if(!b)return;const p=catalog.find(p=>p.id===b.dataset.place);open(`${tile(p)}<p class="eyebrow">${p.categories.join(' · ')}</p><h2 id="dialog-title">${p.name}</h2><p>${p.description}</p><p>${p.location}</p><div class="demo-banner">Beneficios · Próximamente<br>No hay promociones ni afiliación confirmada con este lugar.</div><div class="links"><a class="button primary" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+' '+p.location+' Ciudad de México')}">Cómo llegar ↗</a>${p.id==='malafama'?'':`<a class="button" target="_blank" rel="noopener noreferrer" href="${p.official}">${['felina','pata'].includes(p.id)?'Canal social identificado':'Canal del lugar'} ↗</a>`}</div><p class="small">${p.verification}</p><details><summary>Fuentes y procedencia</summary><p class="small">Consulta: 5 de noviembre de 2026. ${p.image.provenance}</p><ul class="source-list">${p.sources.map(url=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${new URL(url).hostname} ↗</a></li>`).join('')}</ul></details><p class="small">Selección editorial para presentar el concepto. La inclusión no implica afiliación ni beneficios vigentes.</p>`);};
$('#features').innerHTML=features.map(([title],i)=>`<button class="feature" data-feature="${i}"><span>PRÓXIMAMENTE</span><strong>${title}</strong><i aria-hidden="true">↗</i></button>`).join('');
$('#features').onclick=e=>{const b=e.target.closest('[data-feature]');if(b){const [title,desc]=features[+b.dataset.feature];open(`<p class="eyebrow">PRÓXIMAMENTE · VISIÓN DEL PRODUCTO</p><h2 id="dialog-title">${title}</h2><p>${desc}</p><p class="small">Esta función no está habilitada. La demo presenta una posibilidad futura del proyecto.</p>`);}};
function demo(){open(`<p class="eyebrow">DEMO PARA NEGOCIOS</p><h2 id="dialog-title">Bar de demostración</h2><div class="demo-banner"><strong>Datos de ejemplo</strong> · Entidad ficticia.<br>Las cifras y ofertas son simuladas. No hay publicaciones, canjes ni clientes reales.</div><div class="demo-tabs" aria-label="Vistas de la demo">${['Resumen','Ofertas','Clientes'].map(t=>`<button data-tab="${t}" aria-pressed="${demoTab===t}">${t}</button>`).join('')}</div><div id="demo-view"></div><div class="demo-tools">${['QR','Notificaciones','Exportar'].map(x=>`<button data-soon="${x}">${x} · Próximamente</button>`).join('')}</div><button class="text-button" id="reset-demo">Restablecer datos de ejemplo</button><p class="small">${storageAvailable?'Los ejemplos se conservan únicamente durante esta sesión del navegador.':'El navegador no permite guardar la sesión. Los ejemplos solo se conservan mientras esta página esté abierta.'}</p>`);renderDemo();}
function chart(values,labels,title){return `<h3>${title}</h3><div class="bars" role="img" aria-label="Datos de ejemplo: ${labels.map((l,i)=>`${l}: ${values[i]}`).join(', ')}">${values.map((v,i)=>`<div style="height:${v}%"><b>${v}%</b><span>${labels[i]}</span></div>`).join('')}</div>`;}
function renderDemo(){const view=$('#demo-view');if(demoTab==='Resumen'){view.innerHTML=`<p class="small">Últimos 30 días · Datos de ejemplo</p><div class="stats"><div class="stat"><strong>248</strong><span>Visitas simuladas</span></div><div class="stat"><strong>62</strong><span>Canjes simulados</span></div><div class="stat"><strong>28%</strong><span>Recurrencia simulada</span></div></div><p style="margin-top:30px">Así podría verse la actividad de un negocio participante. Estas cifras son una ilustración, sin resultados comerciales reales.</p><button class="button" data-tab="Ofertas">Explorar ofertas de ejemplo ↗</button>`;}else if(demoTab==='Clientes'){view.innerHTML=`<p class="small">Información agregada simulada. No contiene datos personales.</p>${chart([60,25,15],['Residentes','Turistas','Referidos'],'Procedencia ilustrativa')}<p class="chart-label">Distribución ficticia de visitantes (100%).</p>${chart([15,35,40,10],['16–18 h','18–20 h','20–22 h','22–00 h'],'Franjas de visita')}<p class="chart-label">Distribución ficticia de visitas (100%). No representa horarios del negocio.</p>`;}else{view.innerHTML=`<button class="button primary" id="new-offer">Crear oferta de ejemplo ＋</button><div id="offers-list">${offers.length?offers.map(o=>`<article><span class="offer-status">${o.paused?'Pausada':'Activa en demo'} · Datos de ejemplo</span><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p><p class="offer-meta">${esc(o.start)} → ${esc(o.end)}<br>${esc(o.from)}–${esc(o.to)} · Cupo: ${o.capacity}</p><button class="text-button" data-preview="${esc(o.id)}">Previsualizar</button> &nbsp; <button class="text-button" data-toggle="${esc(o.id)}">${o.paused?'Reactivar':'Pausar'} ejemplo</button></article>`).join(''):'<p>No hay ofertas de ejemplo. Crea una para explorar la propuesta.</p>'}</div>`;}}
function offerForm(){open(`<p class="eyebrow">BAR DE DEMOSTRACIÓN · DATOS DE EJEMPLO</p><h2 id="dialog-title">Una nueva invitación.</h2><p>Crea un ejemplo. No se publicará ni se enviará a nadie.</p><form id="offer-form"><label>Título<input name="title" maxlength="80" required></label><label>Descripción<textarea name="description" maxlength="350" rows="3" required></textarea></label><div class="form-grid"><label>Fecha de inicio<input name="start" type="date" required></label><label>Fecha de fin<input name="end" type="date" required></label><label>Desde<input name="from" type="time" required></label><label>Hasta<input name="to" type="time" required></label></div><label>Cupo de ejemplo<input name="capacity" type="number" min="0" max="10000" step="1" required></label><p id="form-error" class="form-error" role="alert"></p><div class="actions"><button class="button primary" type="submit">Guardar en demo</button><button class="text-button" type="button" id="cancel-offer">Volver a ofertas</button></div></form>`);const form=$('#offer-form');form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(!d.title.trim()||!d.description.trim()||d.end<d.start||d.to<=d.from||!Number.isInteger(+d.capacity)||+d.capacity<0){$('#form-error').textContent='Revisa los campos: el fin no puede ser anterior al inicio, la hora final debe ser posterior y el cupo debe ser un entero igual o mayor a cero.';return;}offers.push({...d,title:d.title.trim(),description:d.description.trim(),capacity:+d.capacity,id:crypto.randomUUID(),paused:false});const persisted=save();demoTab='Ofertas';demo();toast(persisted?'Ejemplo guardado en este navegador; no se ha publicado':'Ejemplo disponible en esta página; no se pudo guardar la sesión y no se ha publicado');};form.querySelector('[name=end]').onchange=()=>{const s=form.elements.start.value,t=form.elements.end; t.setCustomValidity(t.value<s?'La fecha final no puede ser anterior al inicio.':'');};form.elements.start.onchange=()=>form.elements.end.setCustomValidity(form.elements.end.value&&form.elements.end.value<form.elements.start.value?'La fecha final no puede ser anterior al inicio.':'');}
body.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){demoTab=tab.dataset.tab;demo();}if(e.target.closest('#new-offer'))offerForm();if(e.target.closest('#cancel-offer')||e.target.closest('#back-offers')){demoTab='Ofertas';demo();}const toggle=e.target.closest('[data-toggle]');if(toggle){const o=offers.find(o=>o.id===toggle.dataset.toggle);o.paused=!o.paused;save();renderDemo();toast(o.paused?'Ejemplo pausado; no se ha publicado':'Ejemplo reactivado; no se ha publicado');}const preview=e.target.closest('[data-preview]');if(preview){const o=offers.find(o=>o.id===preview.dataset.preview);open(`<p class="eyebrow">BAR DE DEMOSTRACIÓN · DATOS DE EJEMPLO</p><h2 id="dialog-title">Vista previa</h2><article class="offer-preview"><span class="offer-status">${o.paused?'Pausada':'Activa en demo'} · Sin valor comercial</span><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p><p>${esc(o.start)} → ${esc(o.end)}<br>${esc(o.from)}–${esc(o.to)} · Cupo: ${o.capacity}</p></article><p class="small">Solo es un ejemplo. No es una promoción vigente.</p><button class="button" id="back-offers">Volver a ofertas</button>`);}if(e.target.closest('#reset-demo')){offers=structuredClone(initial);save();demo();toast('Datos de ejemplo restablecidos.');}const soon=e.target.closest('[data-soon]');if(soon)toast(`${soon.dataset.soon}: próximamente. Esta función no está habilitada.`);});
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{demoTab='Resumen';demo();});
$('#pilot').onclick=()=>open(`<p class="eyebrow">PROPUESTA DE PILOTO · EN CONSTRUCCIÓN</p><h2 id="dialog-title">El siguiente encuentro empieza contigo.</h2><p>La Vita propone conectar negocios independientes con residentes y visitantes a través de experiencias del barrio.</p><ol><li><strong>Conversar.</strong> Entender el negocio, su identidad y sus objetivos.</li><li><strong>Diseñar un piloto.</strong> Acordar un beneficio, sus condiciones y la forma de medirlo.</li><li><strong>Aprender juntos.</strong> Revisar resultados agregados y decidir los siguientes pasos.</li></ol><div class="demo-banner">No hay socios confirmados. La incorporación, condiciones comerciales y tratamiento de datos se definirían antes de un piloto real.</div><p>Esta presentación sirve para abrir esa conversación. No captura datos ni envía solicitudes o mensajes.</p>`);
$('#about').onclick=()=>open(`<p class="eyebrow">VISTA PRIVADA</p><h2 id="dialog-title">Una idea para vivir el barrio.</h2><p>La Vita Roma Condesa es un concepto en desarrollo. Esta demo no tiene cuentas, pagos, reservas ni mensajes reales.</p><p>El directorio es editorial. Los negocios no son socios confirmados y no tienen beneficios vigentes en La Vita. Las fotografías corresponden a los establecimientos y enlazan a su fuente editorial u oficial. Su presencia no implica colaboración con La Vita.</p><p>Los datos del panel son ficticios. Solo los ejemplos de ofertas se guardan durante la sesión del navegador. No se usa analítica ni se recogen datos personales.</p><p class="small">Las tipografías se sirven desde este sitio. Los enlaces externos abren servicios de terceros con sus propias políticas.</p>`);
render();
